import { transform } from "./utils.js";
export default {
    tag: "f-file-list",
    jsImport: "lume_cms/components/f-file-list.js",
    async applyChanges(data, changes, field, document, cmsContent) {
        const value = await Promise.all(Object.values(changes[field.name] || {}).map(
        // deno-lint-ignore no-explicit-any
        async (subchanges) => {
            const value = {};
            for (const f of field.fields) {
                await f.applyChanges(value, subchanges, f, document, cmsContent);
            }
            return value;
        }));
        data[field.name] = transform(field, value);
    },
};
